import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"Task Scheduler","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/scheduler/scheduler.md","filePath":"documentation/scheduler/scheduler.md","lastUpdated":1788551488000}`),a={name:`documentation/scheduler/scheduler.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="task-scheduler" tabindex="-1">Task Scheduler <a class="header-anchor" href="#task-scheduler" aria-label="Permalink to “Task Scheduler”">​</a></h1><p>The <strong>Task Scheduler</strong> allows you to schedule automated browser actions — such as opening target websites or closing unwanted tabs — to execute automatically at specific times, recurring intervals, or upon browser launch.</p><hr><h2 id="accessing-task-scheduler" tabindex="-1">Accessing Task Scheduler <a class="header-anchor" href="#accessing-task-scheduler" aria-label="Permalink to “Accessing Task Scheduler”">​</a></h2><ol><li>Open the extension options dashboard.</li><li>Select <strong>Task Scheduler</strong> from the left navigation menu.</li><li>Click <strong>+ Insert a new Task</strong> in the top-right corner to open the configuration modal.</li></ol><hr><h2 id="configuration-options" tabindex="-1">Configuration Options <a class="header-anchor" href="#configuration-options" aria-label="Permalink to “Configuration Options”">​</a></h2><p>Configure task parameters in the creation modal:</p><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Description</th><th>Required</th></tr></thead><tbody><tr><td><strong>Task Title</strong></td><td>Text Input</td><td>A descriptive label for identifying the task.</td><td>Yes</td></tr><tr><td><strong>Type of Task</strong></td><td>Select</td><td>Action to perform: <strong>Open URL</strong> (opens in a new tab) or <strong>Close URL</strong> (closes tabs matching URL pattern).</td><td>Yes</td></tr><tr><td><strong>URL</strong></td><td>Text Input</td><td>Target web address. Supports wildcard patterns (e.g., <code>*example.com*</code> or <code>https://site.com/app/*</code>) for closing tabs.</td><td>Yes</td></tr><tr><td><strong>Timer</strong></td><td>Select</td><td>Execution frequency (One Time, fixed intervals, calendar recurrence, or browser startup).</td><td>Yes</td></tr><tr><td><strong>Date &amp; Time</strong></td><td>Date / Time</td><td>Target execution date and time. Displayed when Timer is set to <strong>One Time</strong>, <strong>Every Day</strong>, or <strong>Every Year</strong>.</td><td>Conditional</td></tr><tr><td><strong>Day</strong></td><td>Select</td><td>Select weekday (Sunday–Saturday for <strong>Every Week</strong>) or calendar day (1–31 for <strong>Every Month</strong>).</td><td>Conditional</td></tr><tr><td><strong>Minute / Seconds</strong></td><td>Number Input</td><td>Custom recurring interval in minutes or seconds (when using <strong>Custom Minute</strong> or <strong>Custom Second</strong>).</td><td>Conditional</td></tr><tr><td><strong>Task Description</strong></td><td>Textarea</td><td>Optional internal notes explaining the purpose of the scheduled task.</td><td>No</td></tr><tr><td><strong>Auto Focus Tab</strong></td><td>Toggle</td><td>Automatically switch active focus to the newly opened tab.</td><td>No</td></tr><tr><td><strong>Pinned Tab</strong></td><td>Toggle</td><td>Pin the tab to keep it persistent on the left of the tab bar.</td><td>No</td></tr><tr><td><strong>Show Notification</strong></td><td>Toggle</td><td>Display a desktop notification upon task execution.</td><td>No</td></tr><tr><td><strong>Active / Inactive</strong></td><td>Toggle</td><td>Enable or pause the task without deleting its configuration.</td><td>No</td></tr></tbody></table><hr><h2 id="timer-options" tabindex="-1">Timer Options Reference <a class="header-anchor" href="#timer-options" aria-label="Permalink to “Timer Options Reference”">​</a></h2><p>Choose the execution schedule that matches your automation requirements:</p><table tabindex="0"><thead><tr><th>Timer</th><th>Schedule Description</th><th>Required Fields</th></tr></thead><tbody><tr><td><strong>One Time</strong></td><td>Executes once at a specific date and time, then automatically becomes inactive.</td><td>Date, Time</td></tr><tr><td><strong>Every 1 / 2 / 5 / 10 / 30 Minute</strong></td><td>Repeats indefinitely at the selected fixed minute interval.</td><td>None</td></tr><tr><td><strong>Every Hour</strong></td><td>Repeats once every hour.</td><td>None</td></tr><tr><td><strong>Every Day</strong></td><td>Runs once every day at the designated time.</td><td>Time</td></tr><tr><td><strong>Every Week</strong></td><td>Runs once weekly on the chosen day of the week at the designated time.</td><td>Day (Weekdays), Time</td></tr><tr><td><strong>Every Month</strong></td><td>Runs once monthly on the selected calendar date (1–31) at the designated time.</td><td>Day (1–31), Time</td></tr><tr><td><strong>Every Year</strong></td><td>Runs annually on the specified calendar date and time.</td><td>Date, Time</td></tr><tr><td><strong>Custom Minute</strong></td><td>Repeats at any user-defined interval in minutes (e.g., every <code>15</code> or <code>45</code> minutes).</td><td>Minute</td></tr><tr><td><strong>Custom Second</strong></td><td>Repeats at a high-frequency interval in seconds (e.g., every <code>30</code> or <code>90</code> seconds).</td><td>Seconds</td></tr><tr><td><strong>On Browser Open</strong></td><td>Triggers automatically each time the browser starts up.</td><td>None</td></tr></tbody></table><hr><h2 id="managing-tasks" tabindex="-1">Managing Tasks <a class="header-anchor" href="#managing-tasks" aria-label="Permalink to “Managing Tasks”">​</a></h2><p>All scheduled tasks are listed in the Task Scheduler dashboard with their title, action type, frequency, and status:</p><ul><li><strong>Edit Task</strong>: Click the pencil icon to modify URLs, timing, or options.</li><li><strong>Toggle Active / Inactive</strong>: Use the status toggle to temporarily pause or resume a task.</li><li><strong>Delete Task</strong>: Click the trash icon to permanently remove the task.</li></ul><div class="tip custom-block"><p class="custom-block-title">Unattended Automation</p><p>Combine scheduled tasks with automated form filling:</p><ul><li>Schedule a task to open your target form URL with <strong>Auto Focus Tab</strong> enabled.</li><li>When your site and form configuration match that URL, Excellent Data Filler will automatically trigger and fill the form upon page load.</li></ul></div>`,18)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};